//! The runtime's own errors: `TransactionError` and `InstructionError`.

use crate::app::errors::{Known, named};

/// `TransactionError` and `InstructionError`, regenerated by
/// `scripts/runtime_errors.py`.
const RUNTIME: &str = include_str!("runtime.tsv");

/// Parsed rows of [`RUNTIME`]. Public so tests can assert the file is whole.
pub fn runtime_rows() -> impl Iterator<Item = Known> {
    named(RUNTIME)
}

/// A runtime error by the name the RPC reports it under.
pub fn runtime(name: &str) -> Option<Known> {
    runtime_rows().find(|known| known.name == name)
}
